SELECT pvs.id, pvs.patient_id, p.name AS patient_name, pvs.record_date, pvs.blood_pressure_systolic, pvs.blood_pressure_diastolic, CONCAT(pvs.blood_pressure_systolic, '/', pvs.blood_pressure_diastolic) AS blood_pressure, pvs.blood_sugar, pvs.blood_sugar_type, CASE pvs.blood_sugar_type WHEN 'fasting' THEN '空腹' WHEN 'postprandial' THEN '餐后' WHEN 'random' THEN '随机' ELSE pvs.blood_sugar_type END AS blood_sugar_type_name, pvs.remarks FROM patient_vital_signs pvs LEFT JOIN patient p ON pvs.patient_id = p.id
AND pvs.patient_id = #{patientId}
AND pvs.record_date >= #{startDate}
AND pvs.record_date <= #{endDate}
ORDER BY pvs.record_date DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM patient_vital_signs pvs


        AND pvs.patient_id = #{patientId}


        AND pvs.record_date >= #{startDate}


        AND pvs.record_date <= #{endDate}

SELECT pvs.id, pvs.patient_id, p.name AS patient_name, pvs.record_date, pvs.blood_pressure_systolic, pvs.blood_pressure_diastolic, CONCAT(pvs.blood_pressure_systolic, '/', pvs.blood_pressure_diastolic) AS blood_pressure, pvs.blood_sugar, pvs.blood_sugar_type, CASE pvs.blood_sugar_type WHEN 'fasting' THEN '空腹' WHEN 'postprandial' THEN '餐后' WHEN 'random' THEN '随机' ELSE pvs.blood_sugar_type END AS blood_sugar_type_name, pvs.remarks FROM patient_vital_signs pvs LEFT JOIN patient p ON pvs.patient_id = p.id WHERE pvs.patient_id = #{patientId}
AND pvs.record_date >= #{startDate}
AND pvs.record_date <= #{endDate}
ORDER BY pvs.record_date ASC

